//! End-to-end metadata recognition on the committed fixtures.
//!
//! The fixtures are generated by `scripts/make-fixtures.py` and carry known answers:
//!
//! * `metadata-embedded.pdf` — `/Info` and XMP both say something, and the XMP values are the
//!   ones the panel must show (source `xmp`, not `info` or the page text);
//! * `metadata-info.pdf` — only `/Info`, and the differently-worded page title must lose;
//! * `metadata-text-layer.pdf` — no embedded metadata at all: the title block, author line,
//!   DOI and footer venue/year have to be recovered from page one;
//! * `metadata-arxiv.pdf` — an arXiv id and no venue, which is a `@misc` entry with a year
//!   derived from the identifier;
//! * `thin-lines.pdf` — no text layer and no metadata: every field stays empty and nothing is
//!   invented (`@misc{untitled}` with no fields).
//!
//! They run through PDFium like the application does; without the library the test announces a
//! skip rather than pretending it passed.

use lyra_reader_core::{DocumentBackend, PageIndex};
use lyra_reader_metadata::{MetadataSource, RecognizedMetadata, recognize};
use lyra_reader_pdfium::PdfiumBackend;
use std::path::PathBuf;

mod common;

fn fixture(name: &str) -> Option<PathBuf> {
    if !lyra_reader_pdfium::is_available() {
        eprintln!("skipping metadata fixtures: PDFium is unavailable");
        return None;
    }
    Some(common::fixture(name))
}

fn recognize_fixture(name: &str) -> Option<RecognizedMetadata> {
    let path = fixture(name)?;
    let backend = PdfiumBackend::open(&path, None).expect("open metadata fixture");
    let embedded = backend.embedded_metadata().expect("read embedded metadata");
    let first_page = backend.raw_text_page(PageIndex(0)).ok();
    let page_height = backend
        .page_info(PageIndex(0))
        .map(|info| info.geometry.crop_box.size.height)
        .unwrap_or(842.0);
    Some(recognize(&embedded, first_page.as_ref(), page_height))
}

#[test]
fn xmp_wins_over_info_and_the_text_layer_and_says_so() {
    let Some(metadata) = recognize_fixture("metadata-embedded.pdf") else {
        return;
    };
    assert_eq!(
        metadata.title.value(),
        Some("Embedded Metadata: A Study of {Braces} & Percent 100%")
    );
    assert_eq!(metadata.title.source, Some(MetadataSource::Xmp));
    assert_eq!(metadata.authors.values, ["Ada Lovelace", "Alan Turing"]);
    assert_eq!(metadata.authors.source, Some(MetadataSource::Xmp));
    assert_eq!(metadata.venue.value(), Some("Journal of Embedded Testing"));
    assert_eq!(metadata.venue.source, Some(MetadataSource::Xmp));
    assert_eq!(metadata.year.value(), Some("2024"));
    assert_eq!(metadata.year.source, Some(MetadataSource::Xmp));
    assert_eq!(metadata.doi.value(), Some("10.1234/embedded.2024.001"));
    assert_eq!(metadata.doi.source, Some(MetadataSource::Xmp));
    assert!(!metadata.title.is_guessed());
    assert!(!metadata.title.is_empty());
}

#[test]
fn the_information_dictionary_is_read_when_xmp_is_absent() {
    let Some(metadata) = recognize_fixture("metadata-info.pdf") else {
        return;
    };
    assert_eq!(metadata.title.value(), Some("Information Dictionary Title"));
    assert_eq!(metadata.title.source, Some(MetadataSource::Info));
    assert_eq!(metadata.authors.values, ["Info Author", "Second Author"]);
    assert_eq!(metadata.authors.source, Some(MetadataSource::Info));
    // The page carries a different title, which must not replace the embedded one.
    assert_eq!(metadata.venue.value(), None);
}

#[test]
fn a_file_with_no_embedded_metadata_is_read_from_the_first_page() {
    let Some(metadata) = recognize_fixture("metadata-text-layer.pdf") else {
        return;
    };
    assert_eq!(
        metadata.title.value(),
        Some("Page One Title: 100% & Under_Score")
    );
    assert_eq!(metadata.title.source, Some(MetadataSource::FirstPage));
    assert!(metadata.title.is_guessed());
    assert_eq!(metadata.authors.values, ["Marek Müller", "Ada Lovelace"]);
    assert_eq!(metadata.authors.source, Some(MetadataSource::FirstPage));
    assert_eq!(
        metadata.venue.value(),
        Some("Proceedings of the 2024 Testing Conference")
    );
    assert_eq!(metadata.venue.source, Some(MetadataSource::PageFurniture));
    assert_eq!(metadata.year.value(), Some("2024"));
    assert_eq!(metadata.doi.value(), Some("10.5555/2024.12345"));
    assert_eq!(metadata.doi.source, Some(MetadataSource::Text));
    assert!(!metadata.doi.is_guessed());
}

#[test]
fn the_generated_entry_escapes_the_fixture_and_uses_the_venue_type() {
    let Some(metadata) = recognize_fixture("metadata-text-layer.pdf") else {
        return;
    };
    let bibtex = metadata.bibtex();
    assert!(
        bibtex.starts_with("@inproceedings{muller2024page,"),
        "{bibtex}"
    );
    assert!(
        bibtex.contains(r"title = {Page One Title: 100\% \& Under\_Score}"),
        "{bibtex}"
    );
    assert!(
        bibtex.contains(r#"author = {Marek M\"uller and Ada Lovelace}"#),
        "{bibtex}"
    );
    assert!(
        bibtex.contains("booktitle = {Proceedings of the 2024 Testing Conference}"),
        "{bibtex}"
    );
    assert!(bibtex.contains("doi = {10.5555/2024.12345}"), "{bibtex}");
    assert!(
        bibtex.contains("url = {https://doi.org/10.5555/2024.12345}"),
        "{bibtex}"
    );
}

#[test]
fn an_arxiv_only_paper_is_misc_and_its_year_is_derived_from_the_id() {
    let Some(metadata) = recognize_fixture("metadata-arxiv.pdf") else {
        return;
    };
    assert_eq!(
        metadata.title.value(),
        Some("An arXiv Paper Without a Venue")
    );
    assert_eq!(metadata.authors.values, ["Grace Hopper"]);
    assert_eq!(metadata.arxiv_id.value(), Some("2303.08774v2"));
    assert_eq!(metadata.arxiv_id.source, Some(MetadataSource::Text));
    assert_eq!(metadata.year.value(), Some("2023"));
    assert_eq!(metadata.year.source, Some(MetadataSource::ArxivDerived));
    assert!(metadata.venue.is_empty());
    let bibtex = metadata.bibtex();
    assert!(bibtex.starts_with("@misc{hopper2023arxiv,"), "{bibtex}");
    assert!(!bibtex.contains("journal ="), "{bibtex}");
    assert!(!bibtex.contains("booktitle ="), "{bibtex}");
    assert!(
        bibtex.contains("howpublished = {arXiv preprint arXiv:2303.08774v2}"),
        "{bibtex}"
    );
}

#[test]
fn a_page_with_no_text_and_no_metadata_stays_empty() {
    let Some(metadata) = recognize_fixture("thin-lines.pdf") else {
        return;
    };
    for (name, field) in [
        ("title", &metadata.title),
        ("authors", &metadata.authors),
        ("venue", &metadata.venue),
        ("year", &metadata.year),
        ("doi", &metadata.doi),
        ("arxiv", &metadata.arxiv_id),
    ] {
        assert!(field.is_empty(), "{name} was invented: {field:?}");
        assert_eq!(field.source, None, "{name} has a source but no value");
        assert_eq!(field.source_code(), "none");
    }
    // No title, no authors, no year: the key is the only structural value, and none of the
    // metadata fields is filled in to make the entry look more complete than the document.
    assert_eq!(metadata.bibtex(), "@misc{untitled\n}\n");
}
